B.af_=s(["atlansil"],t.s)
B.a0T=new A.bn("Amiodarona","Emergencias","FA r\xe1pida o TV con pulso: 150 mg IV en 10 min y luego 1 mg/min; PCR con FV/TV sin pulso: 300 mg en bolo","amp 150 mg/3 ml","","diluir SIEMPRE en dextrosa 5% (en fisiol\xf3gico precipita). Con pulso, pasarla r\xe1pido da hipotensi\xf3n y bradicardia. Flebitis por v\xeda perif\xe9rica",B.af_,B.C,null,null,!1)
